command:
cd .. && T=$(mktemp -d) && (python3 -m http.server 8798 --bind 127.0.0.1 >/dev/null 2>&1 &) && sleep 0.5 && (PYTHONPATH=scripts uv run --isolated --with pydantic --with typer --with httpx --with loguru python3 scripts/explain_project.py cockpit --explainers fixtures/sample.explainers.jsonl --host 127.0.0.1 --port 18771 >/dev/null 2>&1 &) && for i in $(seq 1 30); do curl -sS -o /dev/null 'http://127.0.0.1:18771/api/health' && break; sleep 1; done && curl -sS 'http://127.0.0.1:18771/api/cockpit/services' -o $T/services.json && curl -sS 'http://127.0.0.1:18771/api/cockpit/services?tab_id=999999999' -o $T/services-tab.json && grep -q 'request.json' scripts/explain_project_core/services.py && python3 - $T <<'PY'
import json,sys,pathlib
base=json.load(open(sys.argv[1]+'/services.json'))
tab=json.load(open(sys.argv[1]+'/services-tab.json'))
assert base['schema']=='explain_project.service_health.v1'
ids={s['service']:s for s in base['services']}
assert set(ids)=={'live_evidence','debugger','surf'}
assert ids['debugger']['status']=='NOT_CONFIGURED'  # no --repo bound
assert ids['surf']['status'] in {'ONLINE','OFFLINE','NOT_CONFIGURED'}
assert ids['live_evidence']['status'] in {'ONLINE','OFFLINE','DEGRADED'}
tids={s['service']:s for s in tab['services']}
assert tids['surf']['status'] in {'ONLINE','DEGRADED'}
assert tids['surf']['detail']
print('EXPLAIN_PROJECT_SERVICE_HEALTH_ENDPOINT_OK')
PY
